// Each incoming item carries one asset's raw Binance klines response
// (array of [openTime, open, high, low, close, volume, closeTime, ...]).
// item.json.symbol must be set upstream per branch (see 'symbol' below,
// derived from the originating HTTP Request node's query parameter).
const SYMBOLS = ['BTCUSDT', 'ETHUSDT', 'SOLUSDT'];

function toCandle(row) {
  return {
    openTime: Number(row[0]),
    open: Number(row[1]),
    high: Number(row[2]),
    low: Number(row[3]),
    close: Number(row[4]),
    volume: Number(row[5]),
  };
}

const assets = items.map((item, i) => ({
  symbol: SYMBOLS[i] ?? item.json.symbol,
  klines: (Array.isArray(item.json) ? item.json : item.json.body ?? []).map(toCandle),
}));

return [{ json: { assets } }];
